$table .= '<tr>';
$table .= '<th>Column 1</th>';
$table .= '<th>Column 2</th>';
$table .= '<th>Column 3</th>';
$table .= '</tr>';
$table .= '</thead>';
$table .= '<tbody>';

// Loop through each row of data and add it to the table
