    $table .= '<tr>';
    $table .= '<td>' . $row[0] . '</td>';
    $table .= '<td>' . $row[1] . '</td>';
    $table .= '<td>' . $row[2] . '</td>';
    $table .= '</tr>';
}

// Finish building the HTML table
