  double x2, y2, z2;
  try {
    x2 = double.parse(stdin.readLineSync()!);
    y2 = double.parse(stdin.readLineSync()!);
    z2 = double.parse(stdin.readLineSync()!);
  } catch (e) {
    print('Invalid input. Please enter numeric values only.');
    return;
  }

  // calculate the distance using the Pythagorean theorem
  double dx = x2 - x1;
  double dy = y2 - y1;
  double dz = z2 - z1;
  double distance = sqrt(dx * dx + dy * dy + dz * dz);

  // output the result rounded to two decimal places
  print('The distance between the two points is ${distance.toStringAsFixed(2)} units.');
