function toTitleCase(input: string): string {
  if (!input) {
    throw new Error("No input provided");
  }
  return input
    .toLowerCase()
    .split(" ")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

