// This function checks if a given credit card number is valid or not using the Luhn algorithm.
function validateCreditCardNumber(creditCardNumber) {
  // Remove any spaces or dashes from the credit card number.
  creditCardNumber = creditCardNumber.replace(/\s|-/g, '');

  // Verify that the credit card number is the correct length.
  if (creditCardNumber.length !== 16) {
    return false;
  }

  // Verify that the credit card number is in the correct format.
  if (!/^[0-9]{16}$/.test(creditCardNumber)) {
    return false;
  }

  // Calculate the Luhn checksum of the credit card number.
  let sum = 0;
  let shouldDouble = false;
  for (let I = creditCardNumber.length - 1; I >= 0; i--) {
    let digit = parseInt(creditCardNumber.charAt(i), 10);

    if (shouldDouble) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    shouldDouble = !shouldDouble;
  }

  // The credit card number is valid if the sum is evenly divisible by 10.
  return sum % 10 === 0;
}

// Test the function with valid and invalid credit card numbers.
console.log(validateCreditCardNumber('4111 1111 1111 1111')); // Expected output: true
console.log(validateCreditCardNumber('6011-1111-1111-1117')); // Expected output: true
console.log(validateCreditCardNumber('1234 5678 9012 3456')); // Expected output: false
console.log(validateCreditCardNumber('5105-1051-0510-5100')); // Expected output: false

Function isPowerOfThree(num) {
  if (num <= 0) {
    return false;
  }
  while (num > 1) {
    if (num % 3 !== 0) {
      return false;
    }
    num /= 3;
  }
  return true;
}

// Example usage:
console.log(isPowerOfThree(27)); // true
console.log(isPowerOfThree(9)); // true
console.log(isPowerOfThree(5)); // false
console.log(isPowerOfThree(0)); // false
console.log(isPowerOfThree(-27)); // false

Here is the code for a recursive function in C# that takes an integer as input and finds the sum of its digits:

```csharp
// This function takes an integer as input and returns the sum of its digits.
// If the input is negative, this function applies the same logic to its absolute value.
// If the input is zero or empty, the function returns 0.

public static int DigitSum(int number)
{
    // Base case: the input is zero or empty, so return 0.
    if (number == 0)
    {
        return 0;
    }

    // Recursive case: add the last digit of the input to the sum of the rest of the digits.
    // To find the last digit, we take the input modulo 10.
    // To find the rest of the digits, we divide the input by 10 and pass it back into the function.
    // If the input is negative, we apply this logic to its absolute value instead.
    if (number < 0)
    {
        return DigitSum(-number);
    }
    else
    {
        return number % 10 + DigitSum(number / 10);
    }
}
```

To use this function, simply call `DigitSum` with an integer argument:

```csharp
int sum = DigitSum(12345);
// sum is now 15
```

Void reverseArray(int arr[], int size) {
   // handle empty array and size 1 array
   if(size == 0 || size == 1) {
      return;
   }

   // initialize variables for swapping
   int left = 0;
   int right = size - 1;

   // loop through array and swap elements in-place
   while(left < right) {
      int temp = arr[left];
      arr[left] = arr[right];
      arr[right] = temp;
      left++;
      right--;
   }
}

