```swift
func calculateGCD() {
    print("Enter the first positive integer:")
    guard let num1 = Int(readLine() ?? ""), num1 > 0 else {
        print("Invalid input. Please enter a positive integer.")
        calculateGCD()
        return
    }
    print("Enter the second positive integer:")
    guard let num2 = Int(readLine() ?? ""), num2 > 0 else {
        print("Invalid input. Please enter a positive integer.")
        calculateGCD()
        return
    }

    var n1 = num1
    var n2 = num2

    // find GCD using Euclidean algorithm
    while n2 != 0 {
        let temp = n2
        n2 = n1 % n2
        n1 = temp
    }

    // print result
    print("The greatest common divisor of \(num1) and \(num2) is \(n1)")
}

calculateGCD()
