// Import necessary packages
import java.util.Scanner;
import java.text.DecimalFormat;

// Create a class for the program
public class CoordinatesDistance {

    // Define a constant for the radius of the Earth in miles
    private static final double EARTH_RADIUS_MI = 3959;

    // Define a constant for the radius of the Earth in kilometers
    private static final double EARTH_RADIUS_KM = 6371;

    // Define a scanner object for user input
    private static Scanner userInput;

    // Define a decimal format object for rounding distances
    private static DecimalFormat df;

    // Define a main method for the program
    public static void main(String[] args) {

        // Initialize the scanner object
        userInput = new Scanner(System.in);

        // Initialize the decimal format object
        df = new DecimalFormat("#.##");

        // Prompt the user to input the coordinates of the first point
        System.out.println("Enter the latitude and longitude coordinates of the first point separated by a space:");
        double lat1 = getUserInput();
        double lon1 = getUserInput();

        // Prompt the user to input the coordinates of the second point
        System.out.println("Enter the latitude and longitude coordinates of the second point separated by a space:");
        double lat2 = getUserInput();
        double lon2 = getUserInput();

        // Calculate the distance between the two points in miles and kilometers
        double miles = calculateDistance(lat1, lon1, lat2, lon2, EARTH_RADIUS_MI);
        double km = calculateDistance(lat1, lon1, lat2, lon2, EARTH_RADIUS_KM);

        // Output the distance in miles and kilometers
        System.out.println("The distance between the two points is " + df.format(miles) + " miles or " + df.format(km) + " kilometers.");

    }

    // Define a method to get input from the user and handle invalid inputs
    private static double getUserInput() {

        while (true) {
            try {
                return Double.parseDouble(userInput.next());
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Please enter a valid number.");
            }
        }

    }

    // Define a method to calculate the distance between two points on a map
    private static double calculateDistance(double lat1, double lon1, double lat2, double lon2, double radius) {

        // Convert the latitude and longitude coordinates to radians
        double lat1Rad = Math.toRadians(lat1);
        double lon1Rad = Math.toRadians(lon1);
        double lat2Rad = Math.toRadians(lat2);
        double lon2Rad = Math.toRadians(lon2);

        // Calculate the differences in latitude and longitude
        double deltaLat = lat2Rad - lat1Rad;
        double deltaLon = lon2Rad - lon1Rad;

        // Calculate the distance using the haversine formula
        double a = Math.pow(Math.sin(deltaLat / 2), 2) + Math.cos(lat1Rad) * Math.cos(lat2Rad) * Math.pow(Math.sin(deltaLon / 2), 2);
        double c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        double distance = radius * c;

        return distance;

    }

}

This program prompts the user to input the latitude and longitude coordinates of two points on a map, handles invalid input, and calculates and outputs the distance between the two points in miles and kilometers. The program utilizes classes and methods for code reuse and readability. The main method calls the getUserInput and calculateDistance methods to handle user input and perform the distance calculation. The getUserInput method handles invalid input by continuously prompting the user until they enter a valid number. The calculateDistance method uses the haversine formula to calculate the distance between two points on a map, given their latitude and longitude coordinates and the radius of the Earth in either miles or kilometers. The program also uses a decimal format object to round the distance output to two decimal places.

