Decrypted: [72, 101, 108, 108, 111, 44, 32, 119, 111, 114, 108, 100, 33]
```

As you can see, the program successfully encrypts and decrypts the message using the specified key and IV. You can modify the key, IV, and plaintext inputs to test different messages and encryption configurations.

# Perl code for implementing a Stack data structure

#!/usr/bin/perl

# Define the Stack class
package Stack;

# Constructor
sub new {
    my ($class) = @_;
    my @stack;  # Initialize an empty array to store the stack data
    my $self = {\@stack};  # Create a hash reference to the stack data
    bless($self, $class);  # Convert the hash reference to an object of the Stack class and return it
    return $self;
}

# Method to push an element onto the top of the stack
sub push {
    my ($self, $element) = @_;
    my $stack = $self->{stack};
    push(@$stack, $element);  # Push the element onto the top of the stack
}

# Method to pop the top element off the stack
sub pop {
    my ($self) = @_;
    my $stack = $self->{stack};
    return pop(@$stack);  # Pop the top element off the stack and return it
}

# Method to check if the stack is empty
sub is_empty {
    my ($self) = @_;
    my $stack = $self->{stack};
    return (@$stack == 0);  # Check if the stack array is empty and return the boolean result
}

# Method to get the current number of elements in the stack
sub size {
    my ($self) = @_;
    my $stack = $self->{stack};
    return scalar(@$stack);  # Return the number of elements in the stack
}

1;  # End of the Stack class

# Example usage of the Stack class
my $stack = Stack->new();

$stack->push("first");
$stack->push("second");
$stack->push("third");

print "Stack size: " . $stack->size() . "\n";  # Output: Stack size: 3

print "Top element: " . $stack->pop() . "\n";  # Output: Top element: third

print "Stack is empty: " . ($stack->is_empty() ? "true" : "false") . "\n";  # Output: Stack is empty: false

print "Stack size: " . $stack->size() . "\n";  # Output: Stack size: 2

