            remainder = num1 % num2;
            num1 = num2;
            num2 = remainder;
        }

        cout << "The greatest common divisor of " << num1 << " and " << num2 << " is " << abs(num1) << "." << endl;

        cout << "Do you want to calculate GCD for another pair of numbers? (Y/N): ";
        cin >> repeat;
    }

