/**
 * Recursive function to find the largest number in an array
 *
 * @param array $arr The array to search
 * @param int $largest The current largest number found
 * @return int The largest number in the array
 */
function findLargestNumber(array $arr, int $largest = PHP_INT_MIN): int
{
    // Loop through each element in the array
    foreach ($arr as $element) {
        if (is_array($element)) {
            // If the element is an array, recursively search it for the largest number
            $largest = findLargestNumber($element, $largest);
        } elseif (is_numeric($element)) {
            // If the element is a number, compare it to the current largest number found
            if ($element > $largest) {
                $largest = $element;
            }
        }
    }

    // Return the largest number found
    return $largest;
}

// Example usage
