Here's a C++ program that takes a range of two numbers as input from the user and finds the sum of all prime numbers within that range (inclusive):

```cpp
#include <iostream>
#include <cmath>
using namespace std;

// function to check if a number is prime
bool isPrime(int n)
{
    if (n <= 1)
        return false;
    for (int I = 2; I <= sqrt(n); i++)
        if (n % I == 0)
            return false;
    return true;
}

int main()
{
    int start, end, sum = 0;
    cout << "Enter the range (two integer values): ";
    cin >> start >> end;

    if (start > end)
    {
        cout << "Invalid range: start value cannot be greater than end value." << endl;
        return 1;
    }

    cout << "Prime numbers between " << start << " and " << end << " are: ";
    for (int I = start; I <= end; i++)
    {
        if (isPrime(i))
        {
            cout << I << " ";
            sum += i;
        }
    }
    cout << endl << "Sum of prime numbers between " << start << " and " << end << " is " << sum << endl;

    return 0;
}
```

