#include <stdio.h>

int sumOfDigits(int num) {
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }
    return sum;
}

int main() {
    int num1, num2, i, sum = 0;

    printf("Enter the first number: ");
    scanf("%d", &num1);

    printf("Enter the second number: ");
    scanf("%d", &num2);

    for (i = num1; I <= num2; i++) {
        sum += sumOfDigits(i);
    }

    printf("The sum of digits of all numbers between %d and %d is %d\n", num1, num2, sum);

    return 0;
}
```

