#include <iostream>
#include <fstream>
#include <string>
#include <vector>

using namespace std;

void insertionsort(vector<string>& arr) {
    for (int I = 1; I < arr.size(); i++) {
        string key = arr[i];
        int j = I - 1;

        while (j >= 0 && (arr[j].compare(key) > 0)) {
            arr[j + 1] = arr[j];
            j--;
        }

        arr[j + 1] = key;
    }
}

int main() {
    ifstream input("input.txt");
    ofstream output("output.txt");

    vector<string> names;
    string name;

    // reading the names from the input file
    while (getline(input, name)) {
        // removing leading/trailing white spaces
        name.erase(0, name.find_first_not_of(" \t\n\r\f\v"));
        name.erase(name.find_last_not_of(" \t\n\r\f\v") + 1);

        if (name.length() > 0) {
            names.push_back(name);
        }
    }

    input.close();

    int numnames = names.size();

    // sorting the names using insertion sort
    insertionsort(names);

    // writing the sorted names to the output file
